+package compiler.loopopts;
+
+import compiler.lib.ir_framework.*;
+import jdk.test.lib.Asserts;
+import jdk.test.lib.Platform;
+
+/*
+ * @test
+ * @bug 8380089
+ * @summary Test that stores can be elided by peeling the loop.
+ * @library /test/lib /
+ * @run driver ${test.main.class}
+ */
+public class TestRemoveStoresAfterPeeling {
+    private static class A {
+        int v;
+    }
+
+    public static void main(String[] args) {
+        var framework = new TestFramework();
+        framework.addScenarios(new Scenario(0));
+        if (Platform.isDebugBuild()) {
+            // When a store is not removed from a loop after that loop is peeled, there will be
+            // multiple stores in the graph
+            framework.addScenarios(new Scenario(1, "-XX:+StressLoopPeeling"));
+        }
+        framework.start();
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"})
+    private void testStoreHoisting(A a, int v) {
+        for (int i = 1; i < 100; i *= 2) {
+            // Simple case, the store can be hoisted above the loop
+            a.v = v;
+        }
+    }
+
+    @Run(test = "testStoreHoisting")
+    public void runStoreHoisting() {
+        A a = new A();
+        testStoreHoisting(a, 1);
+        Asserts.assertEQ(1, a.v);
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"})
+    private void testStorePeeling1(int limit, A a, int v) {
+        for (int i = 1; i < 100; i *= 2) {
+            // The store does not post-dominate the loop head, so it cannot be hoisted
+            if (i >= limit) {
+                break;
+            }
+
+            a.v = v;
+        }
+    }
+
+    @Run(test = "testStorePeeling1")
+    public void runStorePeeling1() {
+        A a = new A();
+        testStorePeeling1(0, a, 1);
+        Asserts.assertEQ(0, a.v);
+        testStorePeeling1(200, a, 1);
+        Asserts.assertEQ(1, a.v);
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"}, phase = CompilePhase.BEFORE_MACRO_EXPANSION)
+    private A testStorePeeling2(A a1, int v1, float v2) {
+        A a2 = new A();
+        for (int i = 1; i < 100; i *= 2) {
+            // There are 2 independent stores in the loop
+            a2.v = Float.floatToRawIntBits(i * v2);
+            a1.v = v1;
+        }
+        return a2;
+    }
+
+    @Run(test = "testStorePeeling2")
+    public void runStorePeeling2() {
+        A a1 = new A();
+        A a2 = testStorePeeling2(a1, 1, 1);
+        Asserts.assertEQ(1, a1.v);
+        Asserts.assertEQ(Float.floatToRawIntBits(64), a2.v);
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"}, phase = CompilePhase.BEFORE_MACRO_EXPANSION)
+    private A testStorePeeling3(int limit, A a1, int v1, float v2) {
+        A a2 = new A();
+        for (int i = 1; i < 100; i *= 2) {
+            // Combine the previous 2 cases
+            a2.v = Float.floatToRawIntBits(i * v2);
+            if (i >= limit) {
+                break;
+            }
+            a1.v = v1;
+        }
+        return a2;
+    }
+
+    @Run(test = "testStorePeeling3")
+    public void runStorePeeling3() {
+        A a1 = new A();
+        A a2 = testStorePeeling3(0, a1, 1, 1);
+        Asserts.assertEQ(0, a1.v);
+        Asserts.assertEQ(Float.floatToRawIntBits(1), a2.v);
+        a2 = testStorePeeling3(200, a1, 1, 1);
+        Asserts.assertEQ(1, a1.v);
+        Asserts.assertEQ(Float.floatToRawIntBits(64), a2.v);
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"})
+    private int testStorePeeling4(A[] array, A a, int v) {
+        int sum = 0;
+        for (int i = 1; i < 100; i *= 2) {
+            // The store to a.v cannot be directly hoisted because the preceding load array[i].v
+            // may alias it. Peeling preserves the first iteration load-before-store ordering.
+            // Later identical stores are redundant.
+            sum += array[i].v;
+            a.v = v;
+        }
+        return sum;
+    }
+
+    @Run(test = "testStorePeeling4")
+    public void runStorePeeling4() {
+        A[] array = new A[100];
+        for (int i = 0; i < 100; i++) {
+            array[i] = new A();
+        }
+
+        A unrelated = new A();
+        Asserts.assertEQ(0, testStorePeeling4(array, unrelated, 1));
+        Asserts.assertEQ(1, testStorePeeling4(array, array[2], 1));
+        array[2].v = 0;
+        Asserts.assertEQ(0, testStorePeeling4(array, array[1], 1));
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "1"})
+    private int testStorePeeling5(boolean b, A[] array, A a, int v) {
+        int sum = 0;
+        for (int i = 1; i < 100; i *= 2) {
+            // Similar to testStorePeeling4, and this test triggers peeling without
+            // StressLoopPeeling
+            if (b) {
+                break;
+            }
+
+            sum += array[i].v;
+            a.v = v;
+        }
+        return sum;
+    }
+
+    @Run(test = "testStorePeeling5")
+    private void runStorePeeling5() {
+        A[] array = new A[100];
+        for (int i = 0; i < 100; i++) {
+            array[i] = new A();
+        }
+        Asserts.assertEQ(0, testStorePeeling5(true, array, array[2], 1));
+
+        A unrelated = new A();
+        Asserts.assertEQ(0, testStorePeeling5(true, array, unrelated, 1));
+        Asserts.assertEQ(0, testStorePeeling5(false, array, unrelated, 1));
+        Asserts.assertEQ(1, testStorePeeling5(false, array, array[2], 1));
+        array[2].v = 0;
+        Asserts.assertEQ(0, testStorePeeling5(false, array, array[1], 1));
+    }
+
+    @Test
+    private void testStoreNotElided1(int limit, A a, int v) {
+        for (int i = 1; i < 100; i *= 2) {
+            // Cannot elide the store after peeling because it does not dominate the back edge
+            if (i >= limit) {
+                a.v = v;
+            }
+        }
+    }
+
+    @Run(test = "testStoreNotElided1")
+    public void runStoreNotElided1() {
+        A a = new A();
+        testStoreNotElided1(-1, a, 1);
+        Asserts.assertEQ(1, a.v);
+        a.v = 0;
+        testStoreNotElided1(50, a, 1);
+        Asserts.assertEQ(1, a.v);
+        a.v = 0;
+        testStoreNotElided1(200, a, 1);
+        Asserts.assertEQ(0, a.v);
+    }
+
+    @Test
+    private void testStoreNotElided2(A a1, A a2, int v1, int v2) {
+        for (int i = 1; i < 100; i *= 2) {
+            // Cannot elide the store after peeling because there is an interfering store
+            a2.v = Float.floatToRawIntBits(i * v2);
+            a1.v = v1;
+        }
+    }
+
+    @Run(test = "testStoreNotElided2")
+    public void runStoreNotElided2() {
+        A a1 = new A();
+        A a2 = new A();
+        testStoreNotElided2(a1, a2, 1, 1);
+        Asserts.assertEQ(1, a1.v);
+        Asserts.assertEQ(Float.floatToRawIntBits(64), a2.v);
+        a1.v = 0;
+        testStoreNotElided2(a1, a1, 1, 1);
+        Asserts.assertEQ(1, a1.v);
+    }
+
+    @Test
+    @IR(counts = {IRNode.STORE_I, "2"}, phase = CompilePhase.AFTER_PRE_MAIN_POST)
+    private int testPreMainPost(int[] array1, int[] array2, int v) {
+        int sum = 0;
+        for (int i = 0; i < array1.length; i++) {
+            // Iteration split also removes the store from the main-loop. It does not elide the
+            // store in the post-loop, though.
+            sum += array1[i];
+            array2[1] = v;
+        }
+        return sum;
+    }
+
+    @Run(test = "testPreMainPost")
+    public void runPreMainPost() {
+        int[] array1 = new int[100];
+        int[] array2 = new int[100];
+        Asserts.assertEQ(0, testPreMainPost(array1, array2, 1));
+        Asserts.assertEQ(1, testPreMainPost(array1, array1, 1));
+    }
+}
